const cover=document.createElement('dialog');cover.id='beacon-cover';cover.setAttribute('aria-labelledby','cover-title');cover.innerHTML=`<div class="cover-shell"><header class="cover-header"><a class="cover-wordmark" href="#"><span class="cover-brand-mark">B<span>✦</span></span><span>BEACON<small>OF THE EAGLE LLC</small></span></a><label class="cover-language"><span class="sr-only" data-i18n="language"></span><select id="cover-language" data-i18n-label="language"><option value="en">English</option><option value="es">Español</option><option value="it">Italiano</option></select></label></header><div class="cover-hero"><div class="cover-copy"><div class="cover-eyebrow" data-i18n="coverEyebrow"></div><div class="cover-product">BEACON BUSINESS</div><span class="business-seal"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z"/><path d="M8 16V9h8v7M6 16h12M10 12h4"/></svg><span data-i18n="businessSeal"></span></span><h1 id="cover-title" data-i18n="coverHeadline"></h1><p data-i18n="coverBody"></p><button id="enter-workspace" class="cover-cta"><span data-i18n="enterWorkspace"></span><span aria-hidden="true">＋</span></button></div><div class="cover-visual"><div class="cover-orbit"></div><img src="beacon-emblem.png" alt="Beacon eagle and lighthouse emblem" width="480" height="480"><div class="cover-image-caption" data-i18n="coverCaption"></div></div></div><div class="cover-features">${[['▥','coverNumbers','coverNumbersBody'],['▣','coverOrganize','coverOrganizeBody'],['✦','coverLearn','coverLearnBody']].map(([icon,title,body])=>`<article><span>${icon}</span><div><h2 data-i18n="${title}"></h2><p data-i18n="${body}"></p></div></article>`).join('')}</div><footer class="cover-footer"><span>© ${new Date().getFullYear()} Beacon of the Eagle LLC</span><span data-i18n="coverFooter"></span></footer></div>`;document.body.append(cover);
$('#enter-workspace').onclick=()=>cover.close();cover.addEventListener('close',()=>document.body.style.overflow='');$('.cover-wordmark').onclick=e=>{e.preventDefault();cover.close()};$('#cover-language').value=language;$('#cover-language').onchange=e=>{$('#language').value=e.target.value;$('#language').dispatchEvent(new Event('change'))};
function show(){applyLocale();$('#cover-language').value=language;cover.querySelector('img').alt=tr('beaconLogo');cover.showModal();cover.scrollTop=0;document.body.style.overflow='hidden'}
const about=document.createElement('button');about.className='text-button';about.dataset.i18n='aboutBeacon';about.id='about-beacon';about.onclick=show;$('.top-actions').prepend(about);
document.addEventListener('beacon-language',()=>{$('#cover-language').value=language;cover.querySelector('img').alt=tr('beaconLogo');applyLocale()});show();
